S = "Hakeem Force Academy"
QS = [
(S, "What is 60 percent of 100?", ["40", "50", "60", "66"], 2, "60 percent of 100 = 60/100 x 100 = 60.", "Percent means per hundred, so any percent of 100 equals the same number.", [862]),
(S, "The population of a town in the year 2000 is 1600 and it doubles every 5 years. What was the population in 1980?", ["50", "100", "200", "400"], 1, "From 1980 to 2000 is 20 years, which is 4 doublings. So the 1980 population = 1600 / 2 / 2 / 2 / 2 = 100.", "Going back in time with doubling means halving at each step.", [614]),
(S, "If the 3rd day of a month is Monday, which day will the 17th be?", ["Sunday", "Monday", "Tuesday", "Saturday"], 1, "From the 3rd to the 17th is 14 days, which is exactly two weeks. So the 17th is also a Monday.", "A gap that is a multiple of 7 days gives the same weekday.", [608, 348]),
(S, "If the 14th day of a month is Monday, which day will the 24th be?", ["Wednesday", "Friday", "Saturday", "Thursday"], 3, "From the 14th to the 24th is 10 days. 10 = 7 + 3, so move 3 days ahead of Monday: Thursday.", "Divide the gap by 7 and move forward by the remainder.", [604]),
(S, "If the 4th day of a month is Sunday, which day will the 24th be?", ["Friday", "Saturday", "Sunday", "Monday"], 1, "From the 4th to the 24th is 20 days. 20 = 14 + 6, so move 6 days ahead of Sunday: Saturday.", "Moving 6 days ahead is the same as moving 1 day back.", [609]),
(S, "If the 2nd day of a month is Monday, which day will the 28th be?", ["Friday", "Sunday", "Saturday", "Thursday"], 2, "From the 2nd to the 28th is 26 days. 26 = 21 + 5, so move 5 days ahead of Monday: Saturday.", "Weekdays repeat every 7 days.", [606]),
(S, "If the 16th day of a month is Sunday, which day is the 5th of the same month?", ["Wednesday", "Thursday", "Friday", "Tuesday"], 0, "From the 5th to the 16th is 11 days. 11 = 7 + 4, so the 5th is 4 days before Sunday: Saturday, Friday, Thursday, Wednesday. So it is Wednesday.", "For earlier dates, move backwards by the remainder of the gap divided by 7.", [605]),
(S, "If the 5th day of a month is Friday, which day is the 23rd?", ["Monday", "Tuesday", "Wednesday", "Sunday"], 1, "From the 5th to the 23rd is 18 days. 18 = 14 + 4, so move 4 days ahead of Friday: Saturday, Sunday, Monday, Tuesday. So it is Tuesday.", "Two full weeks bring the same weekday back.", [610]),
(S, "Who was the President of Pakistan in 1962, when the second constitution was enforced?", ["Iskander Mirza", "Ayub Khan", "Yahya Khan", "Ghulam Muhammad"], 1, "Field Marshal Muhammad Ayub Khan became President in 1958 and introduced the 1962 Constitution.", "Ayub Khan resigned in March 1969 and handed power to Yahya Khan.", [328]),
(S, "Akbar and Khalid were born in 1970 and 1975 respectively, and Ikram is older than Khalid. Who is the youngest of the three?", ["Akbar", "Khalid", "Ikram", "Cannot be said"], 1, "Khalid (1975) is younger than Akbar (1970), and Ikram is older than Khalid. So Khalid is younger than both and is the youngest.", "In age puzzles, a later birth year means a younger person.", [440]),
(S, "The 24th of January is celebrated as the day of what?", ["World Environment Day", "International Day of Education", "World Health Day", "International Women's Day"], 1, "The UN General Assembly declared 24 January the International Day of Education in 2018.", "The day highlights the role of education in peace and development.", [230]),
(S, "A helicopter needs 50 gallons of fuel to cover 320 km. How many gallons does it need to cover 700 km?", ["95.5", "109.4", "112.0", "125.0"], 1, "Fuel per km = 50/320 = 0.15625 gallons. For 700 km: 0.15625 x 700 = 109.375, about 109.4 gallons.", "Fuel used is directly proportional to the distance covered.", [199]),
(S, "A bus carries 500 passengers, of which 350 are men and the rest are women. What percentage of the passengers are women?", ["25%", "30%", "35%", "40%"], 1, "Women = 500 - 350 = 150. Percentage = 150/500 x 100 = 30%.", "Men are 70% and women 30%, so the two add up to 100%.", [809]),
(S, "Out of 1200 students, 800 boys are present. What percentage of the students are present?", ["60%", "62.5%", "66.67%", "75%"], 2, "Percentage present = 800/1200 x 100 = 2/3 x 100 = 66.67%.", "2/3 as a percentage is about 66.67%.", [762]),
(S, "In which year CE did Abu Jahal die?", ["622", "625", "624", "627"], 2, "Abu Jahal was killed in the Battle of Badr, fought on 17 Ramadan 2 AH, which is March 624 CE.", "Badr was the first major battle between the Muslims and the Quraish of Makkah.", [1086]),
(S, "What part of speech is the word 'against' in the sentence 'He leaned against the wall'?", ["Noun", "Pronoun", "Preposition", "Adjective"], 2, "'Against' shows the relation between 'leaned' and 'the wall', so it is a preposition.", "A preposition is normally followed by a noun or pronoun.", [266]),
(S, "What part of speech is the word 'eat' in the sentence 'Children eat fruit'?", ["Noun", "Pronoun", "Adjective", "Verb"], 3, "'Eat' names an action, so it is a verb.", "A verb expresses an action, a state or an occurrence.", [267]),
(S, "What part of speech is the word 'almost' in the sentence 'He almost fell'?", ["Verb", "Noun", "Adverb", "Adjective"], 2, "'Almost' modifies the verb 'fell' and tells the degree, so it is an adverb.", "Many adverbs answer how, when, where or to what extent.", [1054]),
(S, "In which year was the national flag of Pakistan adopted?", ["1947", "1948", "1956", "1949"], 0, "The Constituent Assembly adopted the flag on 11 August 1947, a few days before independence.", "The flag was designed on the basis of the Muslim League flag, with a white stripe for minorities.", [708]),
(S, "An adverb is a word that mainly modifies a what?", ["Noun", "Verb", "Pronoun", "Conjunction"], 1, "An adverb mainly modifies a verb. It can also modify an adjective or another adverb.", "Adjectives, in contrast, modify nouns and pronouns.", [445]),
(S, "Which country suffered the greatest number of deaths in World War 2?", ["Germany", "Soviet Union", "United States", "Japan"], 1, "The Soviet Union lost about 27 million people, which is more than any other country.", "Poland lost the largest share of its population, about one in six people.", [1216, 1217]),
(S, "Aisam-ul-Haq Qureshi is a famous Pakistani player of which sport?", ["Cricket", "Squash", "Tennis", "Hockey"], 2, "Aisam-ul-Haq Qureshi is Pakistan's best-known tennis player, famous for doubles.", "He reached the US Open men's doubles final in 2010 with Rohan Bopanna.", [726, 1334]),
(S, "Which name of Allah means the Most Merciful?", ["Ar-Rahim", "Al-Malik", "Al-Quddus", "As-Salam"], 0, "Ar-Rahim means the Most Merciful (the Ever-Merciful).", "Ar-Rahman is usually translated as the Most Gracious or the Beneficent.", [1269]),
(S, "Ahmed is 5 years old and Sara is three times his age. How old will Sara be when Ahmed is 11?", ["18", "19", "21", "33"], 2, "Sara is 3 x 5 = 15 now. Ahmed becomes 11 after 6 years, so Sara will be 15 + 6 = 21.", "The age difference between two people always stays the same.", [597]),
(S, "Akbar is 3 years old and his sister is three times his age. How old will his sister be when Akbar is 8?", ["14", "15", "24", "17"], 0, "The sister is 3 x 3 = 9 now. Akbar becomes 8 after 5 years, so she will be 9 + 5 = 14.", "Both people age by the same number of years.", [789]),
]
